def solution(nums):
    N = len(nums)
    ans = 0
    for i in range(N):
        for j in range(N):
            product = nums[i] * nums[j]
            for k in range(N):
                if product == nums[k]:
                    ans += 1
    print(ans)

def main():
    n = int(input())
    solution([int(input()) for _ in range(n)])

if __name__ == "__main__":
    main()
